// ringbuffer.go
// A fixed-size ring buffer of float64 samples. Not safe for concurrent use.
package metrics

type Ring struct {
	buf  []float64
	head int
	full bool
}

func NewRing(n int) *Ring {
	if n <= 0 {
		panic("metrics: ring size must be positive")
	}
	return &Ring{buf: make([]float64, n)}
}

// Push appends v, overwriting the oldest sample once the buffer is full.
func (r *Ring) Push(v float64) {
	r.buf[r.head] = v
	r.head = (r.head + 1) % len(r.buf)
	if r.head == 0 {
		r.full = true
	}
}

// Mean returns the average of the stored samples, or 0 when empty.
func (r *Ring) Mean() float64 {
	n := r.Len()
	if n == 0 {
		return 0
	}
	sum := 0.0
	for i := 0; i < n; i++ {
		sum += r.buf[i]
	}
	return sum / float64(n)
}

func (r *Ring) Len() int {
	if r.full {
		return len(r.buf)
	}
	return r.head
}

