// debounce.js
// Returns a function that delays calling fn until `wait` ms have passed
// since the last time it was invoked. Handy for search boxes and resize handlers.

export function debounce(fn, wait = 200, { leading = false } = {}) {
  let timer = null;

  function debounced(...args) {
    const callNow = leading && timer === null;
    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (!leading) fn.apply(this, args);
    }, wait);
    if (callNow) fn.apply(this, args);
  }

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
  };

  return debounced;
}

