/* ringbuf.c - fixed-size byte ring buffer */
#include <stddef.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    uint8_t *buf;
    size_t   cap;
    size_t   head;   /* next write position */
    size_t   tail;   /* next read position */
    size_t   len;
} ringbuf_t;

void rb_init(ringbuf_t *rb, uint8_t *storage, size_t cap) {
    rb->buf = storage;
    rb->cap = cap;
    rb->head = rb->tail = rb->len = 0;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *src, size_t n) {
    size_t space = rb->cap - rb->len;
    if (n > space) n = space;          /* drop what does not fit */
    for (size_t i = 0; i < n; i++) {
        rb->buf[rb->head] = src[i];
        rb->head = (rb->head + 1) % rb->cap;
    }
    rb->len += n;
    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *dst, size_t n) {
    if (n > rb->len) n = rb->len;
    for (size_t i = 0; i < n; i++) {
        dst[i] = rb->buf[rb->tail];
        rb->tail = (rb->tail + 1) % rb->cap;
    }
    rb->len -= n;
    return n;
}

