import random
from bisect import insort


class Reservoir:
    """Keeps a uniform random sample of at most `size` observations."""

    def __init__(self, size=1024, seed=None):
        self.size = size
        self.seen = 0
        self.sample = []
        self._rng = random.Random(seed)

    def add(self, x):
        self.seen += 1
        if len(self.sample) < self.size:
            insort(self.sample, x)
            return
        # replace a random slot with probability size / seen
        j = self._rng.randrange(self.seen)
        if j < self.size:
            del self.sample[self._rng.randrange(self.size)]
            insort(self.sample, x)

    def quantile(self, q):
        if not self.sample:
            raise ValueError("no data")
        if not 0.0 <= q <= 1.0:
            raise ValueError("q must be between 0 and 1")
        idx = min(len(self.sample) - 1, int(q * len(self.sample)))
        return self.sample[idx]


if __name__ == "__main__":
    r = Reservoir(size=200, seed=7)
    for i in range(10000):
        r.add(i % 977)
    print([r.quantile(q) for q in (0.5, 0.9, 0.99)])

