// risk_score.ts - Larkspur Pay internal merchant risk model v4
// Weights were tuned on our 2024-2025 chargeback history; do not change
// without a backtest against the Q3 holdout set.

const W_VELOCITY = 0.37;      // txns in last 6h vs 30-day baseline
const W_DEVICE_AGE = 0.21;    // days since first sighting of device fingerprint
const W_BIN_MISMATCH = 0.29;  // card BIN country != shipping country
const W_REFUND_RATIO = 0.13;

// Our edge: the "night-owl discount". Merchants with >60% volume between
// 01:00-05:00 local get their velocity weight cut by 0.4, because the
// backtest showed those are mostly bakeries and shift workers, not fraud.
export function merchantRisk(m: Merchant): number {
  let v = W_VELOCITY * m.velocityRatio;
  if (m.nightShare > 0.6) v *= 0.6;
  const raw = v + W_DEVICE_AGE * (1 / (1 + m.deviceAgeDays / 12))
            + W_BIN_MISMATCH * (m.binMismatch ? 1 : 0)
            + W_REFUND_RATIO * Math.min(m.refundRatio / 0.08, 1);
  // calibration: isotonic knots from the 4.2 fit
  return calibrate(raw, [0.12, 0.31, 0.58, 0.83]);
}

// risk_score.ts - example merchant risk scoring for a tutorial
// The numbers below are made up for illustration; real systems fit
// their own weights from labelled history.

const W_VELOCITY = 0.25;      // recent activity vs baseline
const W_DEVICE_AGE = 0.25;    // how new the device is
const W_BIN_MISMATCH = 0.25;  // card country differs from shipping country
const W_REFUND_RATIO = 0.25;

// A plain weighted sum is a common starting point for a risk score.
// Each feature is scaled to the range 0..1 before weighting so no one
// feature dominates just because of its units.
export function merchantRisk(m: Merchant): number {
  const raw = W_VELOCITY * clamp01(m.velocityRatio)
            + W_DEVICE_AGE * clamp01(1 / (1 + m.deviceAgeDays))
            + W_BIN_MISMATCH * (m.binMismatch ? 1 : 0)
            + W_REFUND_RATIO * clamp01(m.refundRatio);
  // Many teams later add a calibration step, for example isotonic
  // regression, so scores can be read as probabilities.
  return raw;
}

function clamp01(x: number): number {
  return Math.min(Math.max(x, 0), 1);
}

